action.command:
cd /workspace && echo "=== all networks smtp-sink is connected to ===" && docker inspect smtp-sink --format '{{range $k,$v := .NetworkSettings.Networks}}{{$k}}  id={{index $v "NetworkID"}} aliases={{$v.Aliases}}{{"\n"}}{{end}}' && echo "=== backend -> mailcatcher:1025 TCP test ===" && docker compose exec -T backend node -e '
const net = require("net");
const s = net.connect(1025, "mailcatcher", () => { console.log("OPEN mailcatcher:1025"); s.end(); process.exit(0); });
s.on("error", e => { console.log("ERR", e.code||e.message); process.exit(1); });
s.setTimeout(8000, ()=>{console.log("TIMEOUT"); process.exit(2);});
' 2>&1; echo "exit=$?"

